import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, texture, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = textItems.find((i) => i.role === 'headline') ?? textItems[0] ?? { text: 'Collection 2' };

  const width = 512 / 320;
  const height = 1.0;

  const hexNode = (hex) => {
    const n = parseInt((hex || '#000000').replace('#', ''), 16);
    if (Number.isNaN(n)) return vec3(0, 0, 0);
    return vec3(((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255);
  };

  const ink = hexNode(colors.ink);
  const surface = hexNode(colors.surface);
  const paper = hexNode(colors.paper);
  const accent = hexNode(colors.accent);

  const grain = (u) => {
    const p = u.mul(vec2(512.0, 320.0));
    const h = fract(sin(p.dot(vec2(12.9898, 78.233))).mul(43758.5453));
    return h.sub(0.5).mul(0.035);
  };

  const gradient = mix(surface, ink, smoothstep(0.0, 1.0, uv().y));
  const topAccent = mix(gradient, accent, smoothstep(0.85, 1.0, uv().y).mul(0.06));
  const fallbackColor = topAccent.add(grain(uv())).add(paper.mul(0.03));

  const material = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
  material.colorNode = fallbackColor;

  const geometry = new THREE.PlaneGeometry(width, height);
  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'collection-card-2-label-plane';

  const group = new THREE.Group();
  group.name = config.id || 'collection-card-2-label';
  group.add(plane);

  const textObj = ctx.fontAtlas.createText(String(headline.text || 'Collection 2'), {
    fontSize: headline.typography?.fontSize ?? 39,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 320,
  });
  textObj.position.set(-width * 0.45, 0.0, 0.01);
  textObj.name = 'collection-card-2-label-headline';
  group.add(textObj);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.flipY = false;
      const texColor = texture(tex, uv());
      const base = mix(texColor.rgb, gradient, 0.35);
      const lit = base.add(grain(uv())).add(paper.mul(0.03));
      const surfaceColor = mix(lit, accent, smoothstep(0.85, 1.0, uv().y).mul(0.06));
      material.colorNode = surfaceColor;
      material.needsUpdate = true;
    });
  }

  const timelines = [];
  const tl = gsap.timeline();
  tl.to(material, { opacity: 1, duration: 0.7, ease: 'power2.out' }, 0);
  tl.from(group.scale, { x: 0.97, y: 0.97, duration: 0.9, ease: 'power4.out' }, 0);
  tl.from(textObj.position, { y: '-=0.12', duration: 0.6, ease: 'power2.out' }, 0);
  timelines.push(tl);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch (e) {} });
    group.remove(plane);
    group.remove(textObj);
    geometry.dispose();
    material.dispose();
  };

  return group;
}
